package br.edu.ifrn.sistemachamados.controller;
import br.edu.ifrn.sistemachamados.dto.request.*;import br.edu.ifrn.sistemachamados.dto.response.*;import br.edu.ifrn.sistemachamados.mapper.ApiMapper;import br.edu.ifrn.sistemachamados.model.*;import br.edu.ifrn.sistemachamados.service.*;import jakarta.validation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/setores") public class SetorController {final SetorService s;final CategoriaService c;public SetorController(SetorService s,CategoriaService c){this.s=s;this.c=c;}private Setor e(SetorRequest r){Setor x=new Setor();x.setNome(r.nome());x.setSigla(r.sigla());return x;}@PostMapping public ResponseEntity<SetorResponse> post(@Valid @RequestBody SetorRequest r){Setor x=s.cadastrar(e(r));return ResponseEntity.status(201).body(ApiMapper.setor(x));}@GetMapping public PageResponse<SetorResponse> list(@RequestParam(required=false)String nome,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){return PageResponse.of(s.listar(nome,WebSupport.page(page,size,sort)),ApiMapper::setor);}@GetMapping("/{id}") public SetorResponse get(@PathVariable Long id){return ApiMapper.setor(s.buscarPorId(id));}@PutMapping("/{id}") public SetorResponse put(@PathVariable Long id,@Valid @RequestBody SetorRequest r){return ApiMapper.setor(s.atualizar(id,e(r)));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT) public void del(@PathVariable Long id){s.excluir(id);}@GetMapping("/{id}/categorias") public PageResponse<CategoriaResponse> cats(@PathVariable Long id,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){return PageResponse.of(c.listarPorSetor(id,WebSupport.page(page,size,sort)),ApiMapper::categoria);}}
